:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-compose .span-2{grid-column:span 2}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-grid-masonry{columns:clamp(1,calc((100vw - 280px)/300),4);column-gap:10px;display:block}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-card-v2{break-inside:avoid;display:inline-block;width:100%;margin:0 0 10px;border:2px solid var(--as-frame);border-radius:var(--as-radius);overflow:hidden;background:var(--as-readability)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-card-body{display:grid;gap:6px;padding:9px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-card-v2 h3{margin:0;font-size:1rem;overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-card-v2 p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-card-v2 a{overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-visual{display:block;border-bottom:1px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-visual img{display:block;width:100%;height:auto;max-height:360px;object-fit:cover;filter:grayscale(1)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-audio{width:calc(100% - 16px);margin:8px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-meta{display:flex;justify-content:space-between;gap:6px;font-size:.7rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em}

/* Messaging + media capture */
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-conversation-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:9px;padding:9px 10px;border:2px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-conversation-head h2{margin:0}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-conversation-head span{font-size:.78rem;font-weight:750}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-thread{height:min(58vh,680px);min-height:350px;overflow:auto;display:flex;flex-direction:column;gap:8px;padding:10px;border:2px solid var(--as-frame);background:var(--as-secondary);scrollbar-gutter:stable}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-v2{width:min(82%,720px);display:grid;gap:6px;padding:9px 11px;border:1px solid var(--as-frame);border-radius:var(--as-radius);background:var(--as-readability)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-v2.is-self{align-self:flex-end;background:var(--as-bright);box-shadow:2px 2px 0 var(--as-frame)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-v2.is-partner{align-self:flex-start}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-v2 p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-meta{display:flex;justify-content:space-between;gap:8px;font-size:.72rem;font-weight:850}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-link{display:block;padding:7px;border:1px solid var(--as-frame);background:var(--as-secondary);overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-attachments{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(190px,100%),1fr));gap:6px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-attachments :is(img,video){display:block;width:100%;max-height:360px;object-fit:contain;filter:grayscale(1)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-compose-v2{display:grid;gap:7px;margin-top:8px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-toolbar{display:flex;flex-wrap:wrap;gap:5px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-compose-v2 textarea{width:100%;min-height:92px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-send-row{display:flex;align-items:center;justify-content:space-between;gap:8px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-send-row>span{min-width:0;font-size:.78rem;font-weight:800;overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-upload-tray{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(190px,100%),1fr));gap:6px;margin:7px 0}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-upload-tray:empty{display:none}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-upload-chip{min-width:0;display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:7px;align-items:center;padding:6px;border:1px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-upload-chip :is(img,video){width:44px;height:44px;object-fit:cover;filter:grayscale(1)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-upload-chip :is(strong,small){display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-upload-chip button{min-width:34px;min-height:34px;padding:3px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(220px,.7fr);gap:10px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-stage{position:relative;min-height:320px;display:grid;place-items:center;overflow:hidden;border:2px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-stage video{display:block;width:100%;height:100%;max-height:68vh;object-fit:contain;background:var(--as-anchor)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-empty{position:absolute;inset:0;display:grid;place-items:center;font-weight:900}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-empty[hidden]{display:none}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-controls{display:grid;gap:9px;align-content:start;padding:10px;border:2px solid var(--as-frame);background:var(--as-bright)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-captures{display:grid;gap:6px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(190px,.55fr);gap:10px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-stage{display:grid;grid-template-columns:minmax(0,1fr) minmax(130px,.32fr);gap:8px;align-items:end;min-height:360px;padding:8px;border:2px solid var(--as-frame);background:var(--as-anchor)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-video{position:relative;min-width:0;overflow:hidden;border:2px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-video video{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;filter:grayscale(1)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-video span{position:absolute;left:5px;bottom:5px;padding:2px 6px;border:1px solid var(--as-frame);background:var(--as-readability);font-size:.7rem;font-weight:900}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-controls{display:grid;gap:6px;align-content:start;padding:9px;border:2px solid var(--as-frame);background:var(--as-bright)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-controls [data-call-detail]{min-height:42px;padding:7px;border:1px solid var(--as-frame);background:var(--as-secondary);font-size:.78rem;overflow-wrap:anywhere}

/* Alerts inside every draggable jump bubble */
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .jump-alert-preview{grid-column:1/-1;display:grid;gap:4px;max-height:190px;overflow:auto;margin:2px 0;padding:4px;border:1px solid var(--as-frame);background:var(--as-readability)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .jump-alert-preview>button{display:grid;gap:1px;min-height:0;padding:5px;text-align:left;border:1px solid var(--as-frame);background:var(--as-secondary)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .jump-alert-preview :is(strong,span){display:block;max-width:100%;font-size:.68rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-list{display:grid;gap:7px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:start;padding:9px;border:1px solid var(--as-frame);background:var(--as-bright)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2 :is(strong,p,small){display:block;margin:0;overflow-wrap:anywhere}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2 p{margin-top:3px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2 small{font-size:.7rem;font-weight:800;text-align:right}

@media(max-width:900px){
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-public-profile-layout{grid-template-columns:minmax(170px,240px) minmax(0,1fr)}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-internal-profile-grid{grid-template-columns:minmax(170px,220px) minmax(0,1fr)}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-camera-layout,
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-layout{grid-template-columns:1fr}
}
@media(max-width:680px){
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-tabs button{width:100%}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-form-grid,
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-link-editor{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-form-grid .span-2,
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-social-link-editor .span-2{grid-column:auto}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-internal-profile-grid,
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-public-profile-layout{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-internal-profile-rail{margin-top:-48px}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-internal-profile-main{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-public-profile-header{grid-template-columns:auto minmax(0,1fr);align-items:end}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-public-donate{grid-column:1/-1;width:100%;text-align:center}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-public-preview-media,
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-grid-masonry{columns:1}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-feed-composer-row{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-feed-comment-form{grid-template-columns:1fr auto}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-compose{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-pin-compose .span-2{grid-column:auto}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-message-v2{width:92%}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-stage{grid-template-columns:1fr;min-height:260px}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-call-video.local{width:min(55%,230px);justify-self:end}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2{grid-template-columns:1fr}
  :is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-alert-card-v2 small{text-align:left}
}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-profile-reward-list{display:grid;gap:5px}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-profile-reward-list article{display:grid;gap:2px;padding:6px 7px;border:1px solid var(--as-frame);background:var(--as-readability)}
:is(#merged-admin-space__desktop-surface,#merged-admin-space__mobile-surface) .ourspace-profile-reward-list :is(strong,small){display:block;overflow-wrap:anywhere}

/* ===== OURSPACE PUBLIC VISITOR — MYSPACE × PINTEREST × LINKTREE, GRAYSCALE ===== */
html[data-ourspace-public-visitor="true"] body{
  margin:0;
  min-height:100vh;
  overflow-x:hidden;
  background:#DBDBDB;
  color:#000000;
}
html[data-ourspace-public-visitor="true"] :is(
  #merged-admin-space__desktop-surface,
  #merged-admin-space__mobile-surface,
  #merged-admin-space__games-apps-surface,
  #merged-admin-space__mobile-modules-surface,
){display:none!important}
.ourspace-public-visitor{
  --as-lightest:#FFFFFF;
  --as-lighter:#DBDBDB;
  --as-pale:#B6B6B6;
  --as-bright:#929292;
  --as-anchor:#6D6D6D;
  --as-deep:#494949;
  --as-darker:#242424;
  --as-darkest:#000000;
  --as-background:var(--as-lighter);
  --as-secondary:var(--as-pale);
  --as-control:var(--as-bright);
  --as-strong:var(--as-anchor);
  --as-frame:var(--as-deep);
  --as-separator:var(--as-darker);
  --as-readability:var(--as-lightest);
  --as-ink:var(--as-darkest);
  --as-inverse:var(--as-lightest);
  width:100%;
  min-height:100vh;
  padding:clamp(8px,2vw,24px);
  background:var(--as-background);
  color:var(--as-ink);
  font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
}
.ourspace-public-visitor *,.ourspace-public-visitor *::before,.ourspace-public-visitor *::after{box-sizing:border-box}
.ourspace-public-visitor-shell{width:min(1180px,100%);margin:0 auto;border:1px solid var(--as-frame);background:var(--as-readability);box-shadow:5px 5px 0 var(--as-anchor),8px 8px 0 var(--as-deep)}
.ourspace-public-visitor-topbar{position:sticky;top:0;z-index:20;display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;align-items:center;padding:9px 12px;border-bottom:1px solid var(--as-frame);background:var(--as-anchor);color:var(--as-inverse)}
.ourspace-public-visitor-brand{font-size:clamp(1.15rem,2.4vw,1.65rem);font-weight:1000;letter-spacing:.03em;color:var(--as-inverse);text-decoration:none}
.ourspace-public-visitor-share{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px;align-items:center;min-width:0}
.ourspace-public-visitor :is(input,button,.button,a.button){font:inherit}
.ourspace-public-visitor input{width:100%;min-width:0;min-height:38px;padding:7px 9px;border:1px solid var(--as-frame);border-radius:3px;background:var(--as-readability);color:var(--as-ink)}
.ourspace-public-visitor :is(button,.button,a.button){display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:7px 11px;border:1px solid var(--as-deep);border-radius:3px;background:linear-gradient(180deg,var(--as-pale) 0 3px,var(--as-bright) 3px 59%,var(--as-anchor) 59% 82%,var(--as-deep) 82% 100%);color:var(--as-ink);font-weight:800;text-decoration:none;cursor:pointer;box-shadow:2px 2px 0 var(--as-anchor)}
.ourspace-public-visitor :is(button,.button,a.button):focus-visible,.ourspace-public-visitor a:focus-visible{outline:2px solid var(--as-separator);outline-offset:2px}
.ourspace-public-visitor-loading,.ourspace-public-visitor-error{min-height:58vh;display:grid;place-items:center;padding:24px;text-align:center;background:var(--as-secondary)}
.ourspace-public-visitor-error{align-content:center;gap:10px}
.ourspace-public-visitor-error h1,.ourspace-public-visitor-error p{margin:0}
.ourspace-public-visitor-card{min-width:0;background:var(--as-readability)}
.ourspace-public-visitor-banner{width:100%;height:clamp(180px,28vw,330px);display:grid;place-items:center;overflow:hidden;border-bottom:2px solid var(--as-frame);background:repeating-linear-gradient(135deg,var(--as-pale) 0 18px,var(--as-bright) 18px 36px)}
.ourspace-public-visitor-banner img{display:block;width:100%;height:100%;object-fit:cover;filter:grayscale(1)}
.ourspace-public-visitor-header{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:end;padding:0 clamp(12px,2.5vw,24px) 16px;border-bottom:2px solid var(--as-frame);background:var(--as-secondary)}
.ourspace-public-visitor-avatar{width:clamp(112px,15vw,168px);aspect-ratio:1;display:grid;place-items:center;overflow:hidden;margin-top:clamp(-82px,-7vw,-52px);border:4px solid var(--as-frame);border-radius:50%;background:var(--as-readability);font-size:clamp(2rem,5vw,3.4rem);font-weight:1000;box-shadow:4px 4px 0 var(--as-anchor)}
.ourspace-public-visitor-avatar img{width:100%;height:100%;object-fit:cover;filter:grayscale(1)}
.ourspace-public-visitor-identity{min-width:0;padding-top:12px}
.ourspace-public-visitor-identity h1{margin:0;font-size:clamp(1.7rem,4vw,2.8rem);line-height:1.05;overflow-wrap:anywhere}
.ourspace-public-visitor-identity p{margin:6px 0 0;font-size:clamp(.95rem,1.7vw,1.2rem);font-weight:800;overflow-wrap:anywhere}
.ourspace-public-visitor-donate{align-self:center;white-space:nowrap}
.ourspace-public-visitor-layout{display:grid;grid-template-columns:minmax(220px,310px) minmax(0,1fr);gap:14px;padding:14px;background:var(--as-background)}
.ourspace-public-visitor-sidebar,.ourspace-public-visitor-main{min-width:0;display:grid;gap:12px;align-content:start}
.ourspace-public-visitor-box,.ourspace-public-visitor-section{min-width:0;border:2px solid var(--as-frame);background:var(--as-readability);box-shadow:3px 3px 0 var(--as-anchor)}
.ourspace-public-visitor :is(.ourspace-public-visitor-box,.ourspace-public-visitor-section)>h2{margin:0;padding:7px 10px;border-bottom:2px solid var(--as-frame);background:var(--as-secondary);font-size:.86rem;line-height:1.2;text-transform:uppercase;letter-spacing:.06em}
.ourspace-public-visitor-box>p{margin:0;padding:10px;white-space:pre-wrap;overflow-wrap:anywhere}
.ourspace-public-visitor-tags{display:flex;flex-wrap:wrap;gap:6px;padding:10px}
.ourspace-public-visitor-tags span{display:inline-flex;padding:4px 7px;border:1px solid var(--as-frame);border-radius:3px;background:var(--as-secondary);font-weight:800}
.ourspace-public-visitor-projects{display:grid;gap:7px;padding:9px}
.ourspace-visitor-project{display:grid;gap:4px;padding:8px;border:1px solid var(--as-frame);background:var(--as-readability)}
.ourspace-visitor-project :is(strong,p,a){margin:0;overflow-wrap:anywhere}
.ourspace-visitor-project a{color:var(--as-ink);font-weight:800}
.ourspace-public-visitor-links{display:grid;gap:8px;padding:10px}
.ourspace-visitor-link{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 10px;align-items:center;min-height:52px;padding:9px 11px;border:2px solid var(--as-frame);border-radius:4px;background:linear-gradient(135deg,var(--as-readability) 0 calc(100% - 12px),var(--as-pale) calc(100% - 12px));color:var(--as-ink);text-decoration:none;box-shadow:2px 2px 0 var(--as-anchor)}
.ourspace-visitor-link strong{font-size:1rem;overflow-wrap:anywhere}
.ourspace-visitor-link span{grid-column:1;overflow-wrap:anywhere}
.ourspace-visitor-link small{grid-column:2;grid-row:1/3;align-self:center;max-width:22ch;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ourspace-public-visitor-pinboard{padding:10px;columns:3 230px;column-gap:10px}
.ourspace-visitor-pin{break-inside:avoid;display:inline-grid;width:100%;gap:0;margin:0 0 10px;border:2px solid var(--as-frame);border-radius:4px;background:var(--as-readability);box-shadow:2px 2px 0 var(--as-anchor);vertical-align:top;overflow:hidden}
.ourspace-visitor-pin-media{min-width:0;border-bottom:1px solid var(--as-frame);background:var(--as-secondary)}
.ourspace-visitor-pin-media :is(img,video,iframe){display:block;width:100%;max-width:100%;border:0;filter:grayscale(1)}
.ourspace-visitor-pin-media img{height:auto}
