/* ===== SIGNED-IN DBT DIARY CARDS — DONOR GEOMETRY + OURSPACE GRAYSCALE =====
   Geometry, typography, sizing, spacing, borders, responsive behavior, and print layout
   are merged from both william-sheet.txt and jasper-sheet.txt. Those two donor layout
   files are identical except for their heading, so one canonical geometry rule set is used.
   Color roles below intentionally use only the established OurSpace grayscale system.
*/
.ourspace-diary-card-host{
  width:100%;
  min-width:0;
  min-height:12rem;
  overflow:visible;
}
.ourspace-diary-card-module{
  width:100%;
  min-width:0;
  color:var(--as-ink);
  background:var(--as-workspace,var(--as-readability));
}
.ourspace-diary-card-module[hidden],
.ourspace-diary-card-module [data-person-sheet][hidden]{display:none!important;}

.dbt-diary-module, .dbt-diary-module * {
  box-sizing:border-box;
}
.dbt-diary-module {
  --radius:18px;
  width:100%;
  max-width:100%;
  margin:0 auto;
  padding:clamp(.75rem, 1.4vw, 1.25rem);
  border:2px solid;
  border-radius:var(--radius);
  line-height:1.45;
  font-size:15px;
  overflow:hidden;
}
.dbt-diary-module button,
.dbt-diary-module input,
.dbt-diary-module textarea,
.dbt-diary-module select {
  font:inherit;
}
.dbt-diary-module button {
  min-height:46px;
  border:2px solid;
  border-radius:14px;
  padding:.85rem 1.05rem;
  cursor:pointer;
  line-height:1.25;
  white-space:normal;
  overflow-wrap:anywhere;
  text-align:center;
}
.dbt-diary-module button:hover,
.dbt-diary-module button:focus-visible {
  outline:3px solid;
  outline-offset:2px;
  transform:translateY(-1px);
}
.dbt-diary-module input,
.dbt-diary-module textarea,
.dbt-diary-module select {
  width:100%;
  min-height:42px;
  border:2px solid;
  border-radius:12px;
  padding:.62rem .7rem;
  line-height:1.3;
}
.dbt-diary-module input:focus,
.dbt-diary-module textarea:focus,
.dbt-diary-module select:focus {
  outline:3px solid;
  outline-offset:1px;
}
.dbt-diary-module textarea {
  resize:vertical;
  min-height:72px;
}
.dbt-diary-module small,
.dbt-diary-module .scale {
  font-weight:600;
}
.dbt-module-topbar {
  display:grid;
  grid-template-columns:minmax(280px, 1fr) minmax(280px, 440px);
  gap:1rem;
  align-items:stretch;
  margin-bottom:1rem;
}
.dbt-title-card,
.dbt-controls,
.dbt-side-menu,
.dbt-sheet {
  border:2px solid;
  border-radius:var(--radius);
}
.dbt-title-card {
  padding:1rem 1.1rem;
  border-left:9px solid;
}
.dbt-title-card h1 {
  margin:0 0 .35rem;
  font-size:clamp(1.35rem, 2.4vw, 2.15rem);
  line-height:1.12;
  overflow-wrap:anywhere;
}
.dbt-title-card p {
  margin:.25rem 0 .7rem;
  font-weight:700;
}
.dbt-note {
  border:2px solid;
  border-left:9px solid;
  border-radius:14px;
  padding:.8rem .95rem;
  line-height:1.45;
}
.dbt-chip-row {
  display:flex;
  flex-wrap:wrap;
  gap:.55rem;
  margin-top:.8rem;
}
.dbt-chip {
  display:inline-flex;
  align-items:center;
  min-height:34px;
  border:2px solid;
  border-left:8px solid;
  border-radius:999px;
  padding:.42rem .75rem;
  font-size:.92rem;
  font-weight:800;
  line-height:1.25;
  overflow-wrap:anywhere;
}
.dbt-controls {
  display:flex;
  flex-wrap:wrap;
  gap:.75rem;
  align-content:flex-start;
  padding:1rem;
}
.dbt-controls button {
  flex:1 1 150px;
}
.dbt-status {
  width:100%;
  min-height:40px;
  display:flex;
  align-items:center;
  border:2px solid;
  border-left:8px solid;
  border-radius:14px;
  padding:.55rem .75rem;
  font-size:.92rem;
  font-weight:700;
}
.dbt-layout {
  display:grid;
  grid-template-columns:minmax(520px, 620px) minmax(0, 1fr);
  gap:1rem;
  align-items:start;
  width:100%;
}
.dbt-side-menu {
  position:sticky;
  top:.75rem;
  max-height:calc(100vh - 1.5rem);
  overflow:auto;
}
.dbt-side-header {
  padding:1rem 1.1rem;
  border-bottom:2px solid;
}
.dbt-side-header h2 {
  margin:0;
  font-size:1.25rem;
  line-height:1.2;
}
.dbt-side-header p {
  margin:.45rem 0 0;
  line-height:1.35;
}
.dbt-side-body {
  padding:.85rem;
  overflow:auto;
}
.dbt-skill-table {
  width:100%;
  min-width:630px;
  border-collapse:collapse;
  table-layout:fixed;
  font-size:.92rem;
}
.dbt-skill-table th,
.dbt-skill-table td {
  border:2px solid;
  padding:.55rem .45rem;
  vertical-align:middle;
  text-align:center;
  overflow-wrap:anywhere;
  word-break:normal;
  hyphens:auto;
}
.dbt-skill-table th:first-child,
.dbt-skill-table td:first-child {
  text-align:left;
  width:44%;
  padding-left:.75rem;
}
.dbt-skill-table th {
  position:sticky;
  top:0;
  z-index:2;
  line-height:1.2;
}
.dbt-skill-table input[type="checkbox"] {
  width:24px;
  min-width:24px;
  height:24px;
  min-height:24px;
  padding:0;
  cursor:pointer;
}
.dbt-sheet {
  overflow:auto;
}
.dbt-sheet-header {
  display:grid;
  grid-template-columns:minmax(260px, 1.15fr) minmax(280px, .95fr) minmax(260px, .9fr);
  border-bottom:2px solid;
}
.dbt-sheet-header > div {
  padding:1rem;
  border-right:2px solid;
}
.dbt-sheet-header > div:last-child {
  border-right:0;
}
.dbt-sheet-header h2 {
  margin:0 0 .35rem;
  font-size:1.55rem;
  line-height:1.15;
  overflow-wrap:anywhere;
