/* OurSpace grayscale role assignment for the diary cards. */
.ourspace-diary-card-module .dbt-diary-module{
  background:var(--as-workspace,var(--as-readability));
  color:var(--as-ink);
  border-color:var(--as-frame);
}
.ourspace-diary-card-module :is(.dbt-title-card,.dbt-controls,.dbt-side-menu,.dbt-sheet,.dbt-note,.dbt-status,.dbt-section-nav){
  background:var(--as-readability);
  color:var(--as-ink);
  border-color:var(--as-frame);
}
.ourspace-diary-card-module .dbt-title-card{border-left-color:var(--as-anchor);}
.ourspace-diary-card-module :is(.dbt-note,.dbt-status,.dbt-chip,.dbt-used-skills>div,.dbt-session-line,.dbt-metric){border-color:var(--as-anchor);}
.ourspace-diary-card-module :is(.dbt-chip,.dbt-group-row,.dbt-side-header,.dbt-day-toolbar){background:var(--as-secondary);color:var(--as-ink);}
.ourspace-diary-card-module :is(.dbt-skill-table th,.dbt-cell.dbt-header){background:var(--as-anchor);color:var(--as-inverse,#FFFFFF);}
.ourspace-diary-card-module :is(.dbt-skill-table td,.dbt-cell,.dbt-section,.dbt-footer-fields,.dbt-session-line){background:var(--as-readability);color:var(--as-ink);border-color:var(--as-frame);}
.ourspace-diary-card-module :is(button,input,textarea,select){border-color:var(--as-frame);}
