/* ===================== RECORD PLAYER COMPONENT ===================== */
.ourspace-profile-feed-shell{
  color-scheme:light dark;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;

  /* OurSpace Design Bubble role defaults: intentionally grayscale. */
  --accent1:#242424;--accent2:#494949;--accent3:#6D6D6D;
  --fill1:#FFFFFF;--fill2:#DBDBDB;--fill3:#B6B6B6;
  --text1:#000000;--text2:#242424;--text3:#FFFFFF;
  --textborder1:#FFFFFF;--textborder2:#000000;--textborder3:#929292;
  --background1:#DBDBDB;--background2:#B6B6B6;--background3:#929292;
  --overlay-bg-rgba:rgba(219,219,219,.25);--bg-image:none;--media-filter:grayscale(1);--radius:4px;

  /* Player skin is entirely derived from the design roles above. */
  --rp-shell-dark:var(--accent1);
  --rp-shell-mid:var(--accent2);
  --rp-shell-light:var(--accent3);
  --rp-deck-light:var(--fill1);
  --rp-deck-mid:var(--fill2);
  --rp-deck-deep:var(--fill3);
  --rp-screen:var(--text1);
  --rp-screen-2:var(--text2);
  --rp-light-text:var(--text3);
  --rp-metal-light:var(--background1);
  --rp-metal-mid:var(--background2);
  --rp-metal-dark:var(--background3);
  --rp-outline:var(--textborder2);
  --rp-highlight:var(--textborder1);
  --rp-soft-line:var(--textborder3);
  --waveform-color:var(--text3);
  --waveform-shadow:var(--text1);
  --profile-audio-width:190px;
}


/* MySpace-sized test slot. The supplied clone's native audio rule is 190px wide. */
.ourspace-profile-feed-shell .widget-stage{width:100%;display:flex;align-items:flex-start;justify-content:flex-start;padding:0}
.ourspace-profile-feed-shell .profile-audio-slot{width:min(var(--profile-audio-width),100%);min-width:0;position:relative}

.ourspace-profile-feed-shell .retro-player{
  position:relative;
  width:100%;
  min-width:0;
  padding:5px;
  border:1px solid var(--rp-outline);
  border-radius:9px;
  isolation:isolate;
  color:var(--rp-light-text);
  background:
    radial-gradient(circle at 14% 26%,color-mix(in srgb,var(--rp-highlight) 18%,transparent) 0 .5px,transparent .8px),
    radial-gradient(circle at 77% 68%,color-mix(in srgb,var(--rp-outline) 18%,transparent) 0 .5px,transparent .8px),
    repeating-linear-gradient(7deg,color-mix(in srgb,var(--rp-highlight) 3%,transparent) 0 2px,color-mix(in srgb,var(--rp-outline) 4%,transparent) 2px 4px),
    linear-gradient(100deg,var(--rp-shell-dark),var(--rp-shell-light) 18%,var(--rp-shell-mid) 48%,var(--rp-shell-light) 77%,var(--rp-shell-dark));
  box-shadow:0 4px 9px rgba(0,0,0,.34),inset 0 1px 0 color-mix(in srgb,var(--rp-highlight) 28%,transparent),inset 0 -2px 4px rgba(0,0,0,.34);
}
.ourspace-profile-feed-shell .retro-player::before,.ourspace-profile-feed-shell .retro-player::after{content:"";position:absolute;width:4px;height:4px;border-radius:50%;z-index:4;border:.5px solid var(--rp-outline);background:radial-gradient(circle at 35% 30%,var(--rp-highlight) 0 18%,var(--rp-metal-mid) 25%,var(--rp-metal-dark) 72%,var(--rp-outline) 100%);box-shadow:inset 0 .4px .5px color-mix(in srgb,var(--rp-highlight) 60%,transparent)}
.ourspace-profile-feed-shell .retro-player::before{left:3px;top:3px}.ourspace-profile-feed-shell .retro-player::after{right:3px;top:3px}

.ourspace-profile-feed-shell .deck-panel{
  position:relative;
  display:grid;
  grid-template-columns:70px minmax(0,1fr);
  gap:4px;
  min-height:84px;
  padding:4px;
  border-radius:7px;
  border:1px solid var(--rp-outline);
  outline:1px solid var(--rp-metal-dark);
  background:linear-gradient(115deg,var(--rp-deck-light) 0%,var(--rp-deck-mid) 44%,var(--rp-deck-deep) 100%);
  box-shadow:inset 0 0 0 .5px color-mix(in srgb,var(--rp-highlight) 70%,transparent),inset 0 -4px 7px color-mix(in srgb,var(--rp-outline) 7%,transparent);
}
.ourspace-profile-feed-shell .turntable-panel,.ourspace-profile-feed-shell .display-panel{position:relative;min-width:0}
.ourspace-profile-feed-shell .turntable-panel{height:74px;overflow:hidden}

.ourspace-profile-feed-shell .load-cluster{position:absolute;left:0;top:3px;z-index:12;display:grid;justify-items:center;gap:2px}
.ourspace-profile-feed-shell .power-led{width:4px;height:4px;border-radius:50%;background:radial-gradient(circle at 35% 30%,var(--rp-highlight) 0 18%,var(--rp-metal-light) 28%,var(--rp-metal-dark) 70%,var(--rp-outline) 100%);border:.5px solid var(--rp-outline);box-shadow:0 0 2px color-mix(in srgb,var(--rp-highlight) 72%,transparent)}
.ourspace-profile-feed-shell .brass-knob,.ourspace-profile-feed-shell .decor-knob{border-radius:50%;background:radial-gradient(circle at 36% 30%,var(--rp-highlight) 0 10%,var(--rp-metal-light) 28%,var(--rp-metal-mid) 64%,var(--rp-metal-dark) 100%);border:.6px solid var(--rp-outline);box-shadow:inset 0 .6px .7px color-mix(in srgb,var(--rp-highlight) 55%,transparent),0 .7px 1.3px rgba(0,0,0,.34)}
.ourspace-profile-feed-shell .load-knob{position:relative;width:12px;height:12px;padding:0;transition:transform .12s ease,filter .12s ease}
.ourspace-profile-feed-shell .load-knob::after{content:"";position:absolute;width:.8px;height:4px;left:50%;top:1.7px;transform:translateX(-50%);border-radius:1px;background:var(--rp-shell-dark)}
.ourspace-profile-feed-shell .load-knob:hover,.ourspace-profile-feed-shell .load-knob:focus-visible{filter:brightness(1.12)}.ourspace-profile-feed-shell .load-knob:active{transform:rotate(16deg) scale(.96)}

/* Record diameter lands at ~60px: approximately the supplied Design Bubble's 62px desktop orb. */
.ourspace-profile-feed-shell .platter-wrap{position:absolute;left:4px;top:4px;width:66px;height:66px}
.ourspace-profile-feed-shell .platter-rim{width:100%;height:100%;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle at 45% 42%,var(--rp-deck-light) 0 70%,var(--rp-metal-light) 72%,var(--rp-metal-dark) 76%,var(--rp-metal-mid) 79%,var(--rp-shell-dark) 82%,var(--rp-screen) 84% 100%);box-shadow:0 1.5px 3px rgba(0,0,0,.34),inset 0 .8px 1.7px color-mix(in srgb,var(--rp-highlight) 55%,transparent)}
.ourspace-profile-feed-shell .vinyl{position:relative;width:92%;height:92%;border-radius:50%;display:grid;place-items:center;overflow:hidden;background:repeating-radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--rp-highlight) 5%,transparent) 0 .5px,color-mix(in srgb,var(--rp-outline) 8%,transparent) 1px 2px,transparent 2.5px 4px),radial-gradient(circle at 50% 50%,var(--rp-shell-mid) 0 8%,var(--rp-screen) 9% 48%,var(--rp-shell-dark) 60%,var(--rp-screen) 76%,var(--rp-shell-mid) 100%);box-shadow:inset 0 0 5px color-mix(in srgb,var(--rp-highlight) 9%,transparent),inset 0 0 10px rgba(0,0,0,.55),0 .6px 1.2px rgba(0,0,0,.55);animation:vinyl-spin 2.2s linear infinite;animation-play-state:paused;transform-origin:center}
